class Solution {
public:
    vector<int> findRedundantDirectedConnection(vector<vector<int>>& edges) {
        int n = edges.size();
        vector<int> parentEdge(n + 1, 0);
        vector<int> cand1, cand2;
        for (const auto& e : edges) {
            int u = e[0], v = e[1];
            if (parentEdge[v] != 0) {
                cand1 = {parentEdge[v], v};
                cand2 = e;
                break;
            }
            parentEdge[v] = u;
        }
        vector<int> parent(n + 1);
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](auto self, int x) -> int {
            while (parent[x] != x) {
                parent[x] = parent[parent[x]];
                x = parent[x];
            }
            return x;
        };
        for (const auto& e : edges) {
            if (!cand2.empty() && e == cand2) continue;
            int ru = find(find, e[0]), rv = find(find, e[1]);
            if (ru == rv) {
                return !cand1.empty() ? cand1 : e;
            }
            parent[ru] = rv;
        }
        return cand2;
    }
};

class Solution {
    public int[] findRedundantDirectedConnection(int[][] edges) {
        int n = edges.length;
        int[] parentEdge = new int[n + 1];
        int[] cand1 = null, cand2 = null;
        for (int[] e : edges) {
            int u = e[0], v = e[1];
            if (parentEdge[v] != 0) {
                cand1 = new int[]{parentEdge[v], v};
                cand2 = e;
                break;
            }
            parentEdge[v] = u;
        }
        int[] parent = new int[n + 1];
        for (int i = 0; i <= n; i++) parent[i] = i;
        for (int[] e : edges) {
            if (cand2 != null && e[0] == cand2[0] && e[1] == cand2[1]) continue;
            int ru = find(parent, e[0]);
            int rv = find(parent, e[1]);
            if (ru == rv) {
                return cand1 != null ? cand1 : e;
            }
            parent[ru] = rv;
        }
        return cand2;
    }
    private int find(int[] parent, int x) {
        while (parent[x] != x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    }
}

var findRedundantDirectedConnection = function(edges) {
    const n = edges.length;
    const parentEdge = new Map();
    let cand1 = null, cand2 = null;
    for (const [u, v] of edges) {
        if (parentEdge.has(v)) {
            cand1 = [parentEdge.get(v), v];
            cand2 = [u, v];
            break;
        }
        parentEdge.set(v, u);
    }
    const parent = Array.from({ length: n + 1 }, (_, i) => i);
    const find = (x) => {
        while (parent[x] !== x) {
            parent[x] = parent[parent[x]];
            x = parent[x];
        }
        return x;
    };
    for (const [u, v] of edges) {
        if (cand2 && u === cand2[0] && v === cand2[1]) continue;
        const ru = find(u), rv = find(v);
        if (ru === rv) {
            return cand1 ? cand1 : [u, v];
        }
        parent[ru] = rv;
    }
    return cand2;
};
